def is_nested(string):
    open_count = 0
    has_nested = False

    for char in string:
        if char == '[':
            open_count += 1
            if open_count > 1:
                has_nested = True
        elif char == ']':
            open_count -= 1
            if open_count < 0:
                return False

    return has_nested and open_count == 0

